<script setup lang="ts">
import AdminLayout from '@/Layouts/AdminLayout.vue';
import { Head, Link } from '@inertiajs/vue3';
import { computed } from 'vue';

defineOptions({ layout: AdminLayout });
const props = defineProps<{ counts: Record<string, number>; latest: any[] }>();
const total = computed(() => Object.values(props.counts).reduce((sum, value) => sum + Number(value), 0));
const inReview = computed(() => Number(props.counts.administrative_review || 0) + Number(props.counts.curation || 0));
const selected = computed(() => Number(props.counts.selected || 0) + Number(props.counts.shortlisted || 0));
const maxCount = computed(() => Math.max(1, ...Object.values(props.counts).map(Number)));
const statusLabel = (value: string) => ({submitted:'Baru masuk',administrative_review:'Pemeriksaan',revision_requested:'Perlu revisi',eligible:'Memenuhi syarat',curation:'Kurasi',shortlisted:'Shortlist',selected:'Terpilih',not_selected:'Tidak terpilih'}[value] || value.replaceAll('_',' '));
</script>

<template>
    <Head title="Admin Dashboard" />
    <div class="dashboard-page">
        <header class="page-header"><div><p>ADMIN PROGRAM</p><h1>Dashboard</h1><span>Ringkasan aktivitas Original Sessions 2026</span></div><Link href="/admin/submissions" class="primary-action">Lihat Submission <b>→</b></Link></header>
        <section class="stats">
            <article><span>Total submission</span><strong>{{ total }}</strong><small>Semua pendaftaran</small></article>
            <article><span>Baru masuk</span><strong>{{ counts.submitted || 0 }}</strong><small>Menunggu pemeriksaan</small></article>
            <article><span>Dalam proses</span><strong>{{ inReview }}</strong><small>Administrasi & kurasi</small></article>
            <article class="accent"><span>Shortlist & terpilih</span><strong>{{ selected }}</strong><small>Kandidat terbaik</small></article>
        </section>
        <section class="dashboard-grid">
            <article class="panel pipeline"><div class="panel-title"><div><h2>Distribusi tahapan</h2><p>Posisi submission saat ini</p></div><span>{{ total }} total</span></div><div v-if="Object.keys(counts).length" class="bars"><div v-for="(count,status) in counts" :key="status" class="bar-row"><span>{{ statusLabel(String(status)) }}</span><div><i :style="{width:(Number(count)/maxCount*100)+'%'}"></i></div><b>{{ count }}</b></div></div><div v-else class="empty">Belum ada data submission untuk ditampilkan.</div></article>
            <article class="panel latest"><div class="panel-title"><div><h2>Submission terbaru</h2><p>Pendaftar yang baru masuk</p></div><Link href="/admin/submissions">Lihat semua →</Link></div><div v-if="latest.length" class="latest-list"><Link v-for="item in latest.slice(0,6)" :key="item.id" :href="`/admin/submissions/${item.id}`"><span class="song-icon">♪</span><span class="submission-copy"><b>{{ item.song?.title || 'Tanpa judul' }}</b><small>{{ item.applicant?.full_name }} · {{ item.registration_number }}</small></span><em>{{ statusLabel(item.status) }}</em></Link></div><div v-else class="empty">Submission terbaru akan muncul di sini.</div></article>
        </section>
        <section class="panel table-panel"><div class="panel-title"><div><h2>Pendaftaran terbaru</h2><p>Daftar aktivitas submission terakhir</p></div></div><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Pendaftar</th><th>Lagu</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="item in latest" :key="item.id"><td class="number">{{ item.registration_number }}</td><td>{{ item.applicant?.full_name }}</td><td><b>{{ item.song?.title }}</b></td><td><span class="status">{{ statusLabel(item.status) }}</span></td><td><Link :href="`/admin/submissions/${item.id}`">Buka →</Link></td></tr><tr v-if="!latest.length"><td colspan="5" class="empty">Belum ada pendaftaran.</td></tr></tbody></table></div></section>
    </div>
</template>

